import{_ as t,l,o as e,c as n,v as i,p,x as r,d as s,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"准备金利息与走廊","description":"","frontmatter":{"title":"准备金利息与走廊","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ior-corridor-floor.md","filePath":"econ/ior-corridor-floor.md","lastUpdated":1789023840000}'),h={name:"econ/ior-corridor-floor.md"};function E(I,a,_,B,u,A){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="准备金利息与走廊" tabindex="-1">准备金利息与走廊 <a class="header-anchor" href="#准备金利息与走廊" aria-label="Permalink to &quot;准备金利息与走廊&quot;">​</a></h1><div class="epigraph"><p>政策利率是走廊里被站立便利与准备金利息夹住的市场利率；地板系统里数量可以很大，锚仍是利息，不是把 $M$ 当工具请回。</p><footer>—— 据各国央行操作框架的公开讨论；Bindseil 对实施与走廊的系统整理</footer></div><p><a href="/econ/inflation-targeting">上一课</a>把名义锚写成灵活通胀目标，\\(\\pi^*\\) 公开。目标要靠一个可操作的隔夜利率去实现。本课的缺口是实施：准备金需求、存贷款便利、准备金利息（IOR）如何把市场利率钉在走廊或地板上。零下限下一课才问这个利率不能再降时怎么办；本课先在正利率区把操作与数量论的长期 \\(M\\) 分清。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>泰勒规则写出 \\(i^*\\)。银行间隔夜利率是准备金市场的价格。稀缺准备金时代，央行用公开市场把供给对准需求曲线的陡峭段，形成走廊：存款便利给下限、贷款便利给上限。充足准备金（地板）时代，供给落在需求平坦段，IOR 成为有效下限，市场利率贴着它，数量可以远大于最低要求。缺口不是再定义 \\(\\pi^*\\)，而是：同一政策利率，走廊与地板是两套实施， \\(H\\) 的数量含义不同。Bindseil 把实施从「货币数量主义操作」里拆出来：工具是利率，准备金适应。</p><p><span class="marginnote">IOR 是对准备金付息，改变持有准备金的机会成本。它不是铸币税课的通胀税本身，但 \\(i\\) 与 IOR 的利差会影响谁愿意持有 \\(H\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>走廊：上下便利利率包住目标，公开市场微调使隔夜率在包内。地板：IOR 设为政策利率（或极近），超额准备金很多，隔夜率不会系统性低于 IOR（若套利充分）。两种系统都能执行 IT 的 \\(i\\)；差别在资产负债表规模与银行的准备金需求是否还约束。数量方程：\\(P\\) 的长期锚仍在，\\(M\\) 在地板上由需求内生得更「松」——\\(V\\) 下降吸收多余 \\(H\\)，与下限课同一会计。</p>',8)),(e(),p(c,null,{default:r(()=>[d(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IT%5B%22%E9%80%9A%E8%83%80%E7%9B%AE%E6%A0%87%E7%BB%99%E5%87%BA%20i*%22%5D%20--%3E%20COR%5B%22%E8%B5%B0%E5%BB%8A%EF%BC%9A%E4%BE%BF%E5%88%A9%E5%A4%B9%E4%BD%8F%22%5D%0A%20%20IT%20--%3E%20FLR%5B%22%E5%9C%B0%E6%9D%BF%EF%BC%9AIOR%20%E9%94%9A%E4%BD%8F%22%5D%0A%20%20COR%20--%3E%20I%5B%22%E9%9A%94%E5%A4%9C%E5%88%A9%E7%8E%87%20%E2%89%88%20i*%22%5D%0A%20%20FLR%20--%3E%20I%0A%20%20I%20--%3E%20NK%5B%22%E8%BF%9B%E5%85%A5%E6%AC%A7%E6%8B%89%20%2F%20IS%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>CIP 与跨境准备金套利会让离岸美元利率偏离国内走廊。那是市场层平价，实证见<a href="/quant/irp">利率平价</a>，本课不把交叉货币基差当实施失败的充分统计。</p><h3 id="地板不是又一次-qe-定义" tabindex="-1">地板不是又一次 QE 定义 <a class="header-anchor" href="#地板不是又一次-qe-定义" aria-label="Permalink to &quot;地板不是又一次 QE 定义&quot;">​</a></h3><p>QE 改变的是久期与信用构成；地板可以只是把原来走廊里的供给推到平坦段，券种不变。把「资产负债表大」写成松紧，会取消 IT 课已经钉住的利率工具。信号仍可能把规模读成路径承诺——非常规课再拆。</p><h3 id="走廊宽度是实施参数" tabindex="-1">走廊宽度是实施参数 <a class="header-anchor" href="#走廊宽度是实施参数" aria-label="Permalink to &quot;走廊宽度是实施参数&quot;">​</a></h3><p>上下便利拉得太开，市场利率在包内可以漂，IT 的 \\(i^*\\) 执行变差。拉得太近，便利被频繁使用，央行变成主要对手方。</p><p>宽度选择是操作，不是 \\(\\pi^*\\) 本身。本课不把宽度写成宏观松紧。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>银行不愿以低于 IOR 的利率拆出（可把钱放在央行），不愿以高于贷款便利的利率拆入。走廊宽、套利摩擦大，市场利率在包内可以漂。地板上摩擦仍可使隔夜率略偏离 IOR，但政策仍用 IOR 当工具，而不是用准备金数量当工具。长期中性：无论走廊还是地板，一旦 \\(i\\) 路径与 \\(\\pi^*\\) 定了，\\(P\\) 与名义锚对齐，\\(H\\) 的水平由需求与监管（流动性覆盖等）决定。</p><p>从走廊切到地板，往往是危机中把供给推过拐点，事后可以不回去。立场仍由 IOR（或走廊中点）读，不由「准备金多了多少」读。把切换本身当成永久宽松，是把实施存量当成规则。数量论的 \\(MV=Py\\) 在地板上靠 \\(V\\) 吸收多余 \\(H\\)；要抬 \\(P\\)，仍需 \\(i\\) 路径与锚，而不是准备金账户上的整数。</p><p>铸币税：对准备金付息提高了央行的利息成本，缩小利差铸币税。这是财政与央行利润的接头，不是实施框架的目标。本课不估算某年的利润转移。</p><p><span class="marginnote">监管流动性需求会抬升准备金需求曲线，走廊里像「更稀缺」，地板上只是把平坦段垫得更长。不要把 LCR 写成货币政策立场。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写某央行某次改走廊宽度的基点，不把支付系统工程当宏观主干。量化栏没有操作台。有效下限下一课：现金的零利息使 IOR 也不能任意为负。开放经济的跨境准备金是外溢，不是本课的走廊几何。</p><p>非银行不能直接吃 IOR 时，地板上隔夜率可以低于 IOR，套利链断裂。实施仍声明工具是 IOR 与便利，而不是改回外生 \\(M\\)。把「走廊失灵」写成货币政策没有锚，会取消 IT 课的 \\(\\pi^*\\)。摩擦改变的是 \\(i\\) 向政策利率的贴合，不是名义锚的定义。</p><p>后课默认：IT 的 \\(i\\) 由走廊或地板实施；数量适应，工具仍是利率。下一课：这个 \\(i\\) 碰到有效下限，实施框架还在，边际却断了。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>IT 给出要钉的 \\(i^*\\)；本课给出准备金市场如何钉住它。</li><li>走廊用便利夹住；地板用 IOR 在充足准备金上锚住。</li><li>资产负债表规模不是松紧的充分统计。</li><li>CIP 偏离交给 <code>/quant/irp</code>，不当实施失败的定义。</li><li>出处：央行操作框架的公开讨论；Bindseil 对货币政策实施与走廊的整理。</li></ul>',17))])}const R=t(h,[["render",E]]);export{m as __pageData,R as default};
